def check_not_vislist_intent(self):

    syntaxMsg = (
        "The intent that you specified corresponds to more than one visualization. "
        "Please replace the Vis constructor with VisList to generate a list of visualizations. "
        "For more information, see: https://lux-api.readthedocs.io/en/latest/source/guide/vis.html#working-with-collections-of-visualization-with-vislist"
    )

    for i in range(len(self._intent)):
        clause = self._intent[i]
        if isinstance(clause, str):
            if "|" in clause or "?" in clause:
                raise TypeError(syntaxMsg)
        if isinstance(clause, list):
            raise TypeError(syntaxMsg)

def _is_vis_input(self):
    if type(self._input_lst[0]) == Vis:
        return True
    elif type(self._input_lst[0]) == Clause:
        return False

def parse(intent: List[Union[Clause, str]]) -> List[Clause]:
    """
    Given the string description from a list of input Clauses (intent),
    assign the appropriate clause.attribute, clause.filter_op, and clause.value.

    Parameters
    ----------
    intent : List[Clause]
            Underspecified list of lux.Clause objects.

    Returns
    -------
    List[Clause]
            Parsed list of lux.Clause objects.
    """
    if type(intent) != list:
        raise TypeError(
            "Input intent must be a list consisting of string descriptions or lux.Clause objects."
            "\nSee more at: https://lux-api.readthedocs.io/en/latest/source/guide/intent.html"
        )
    import re

    new_context = []
    # checks for and converts users' string inputs into lux specifications
    for clause in intent:
        valid_values = []
        if isinstance(clause, list):
            valid_values = []
            for v in clause:
                # and v in list(ldf.columns): #TODO: Move validation check to Validator
                if type(v) is str:
                    valid_values.append(v)
            temp_spec = Clause(attribute=valid_values)
            new_context.append(temp_spec)
        elif isinstance(clause, Clause):
            new_context.append(clause)
        else:
            if isinstance(clause, str):
                # case where user specifies a filter
                if "=" in clause:
                    eqInd = clause.index("=")
                    var = clause[0:eqInd]
                    if "|" in clause:
                        values = clause[eqInd + 1 :].split("|")
                        for v in values:
                            # if v in ldf.unique_values[var]: #TODO: Move validation check to Validator
                            valid_values.append(v)
                    else:
                        valid_values = clause[eqInd + 1 :]
                    # if var in list(ldf.columns): #TODO: Move validation check to Validator
                    temp_spec = Clause(attribute=var, filter_op="=", value=valid_values)
                    new_context.append(temp_spec)
                # case where user specifies a variable
                else:
                    if "|" in clause:
                        values = clause.split("|")
                        for v in values:
                            # if v in list(ldf.columns): #TODO: Move validation check to Validator
                            valid_values.append(v)
                    else:
                        valid_values = clause
                    temp_spec = Clause(attribute=valid_values)
                    new_context.append(temp_spec)
            else:
                temp_spec = Clause(attribute=clause)
                new_context.append(temp_spec)

    intent = new_context
    for clause in intent:
        if clause.description:
            # TODO: Move validation check to Validator
            # if ((clause.description in list(ldf.columns)) or clause.description == "?"):# if clause.description in the list of attributes
            # clause.description contain ">","<". or "="
            if type(clause.description) == str and any(
                ext in [">", "<", "=", "!="] for ext in clause.description
            ):
                # then parse it and assign to clause.attribute, clause.filter_op, clause.values
                clause.filter_op = re.findall(r"/.*/|>|=|<|>=|<=|!=", clause.description)[0]
                split_description = clause.description.split(clause.filter_op)
                clause.attribute = split_description[0]
                clause.value = split_description[1]
                if re.match(r"^-?\d+(?:\.\d+)?$", clause.value):
                    clause.value = float(clause.value)
            elif type(clause.description) == str:
                clause.attribute = clause.description
            elif type(clause.description) == list:
                clause.attribute = clause.description
            else:  # then it is probably a value
                clause.value = clause.description
    return intent

def __repr__(self):
    all_clause = all([isinstance(unit, lux.Clause) for unit in self._inferred_intent])
    if all_clause:
        filter_intents = None
        channels, additional_channels = [], []
        for clause in self._inferred_intent:

            if hasattr(clause, "value"):
                if clause.value != "":
                    filter_intents = clause
            if hasattr(clause, "attribute"):
                if clause.attribute != "":
                    if clause.aggregation != "" and clause.aggregation is not None:
                        attribute = f"{clause._aggregation_name.upper()}({clause.attribute})"
                    elif clause.bin_size > 0:
                        attribute = f"BIN({clause.attribute})"
                    else:
                        attribute = clause.attribute
                    if clause.channel == "x":
                        channels.insert(0, [clause.channel, attribute])
                    elif clause.channel == "y":
                        channels.insert(1, [clause.channel, attribute])
                    elif clause.channel != "":
                        additional_channels.append([clause.channel, attribute])

        channels.extend(additional_channels)
        str_channels = ""
        for channel in channels:
            str_channels += f"{channel[0]}: {channel[1]}, "

        if filter_intents:
            return f"<Vis  ({str_channels[:-2]} -- [{filter_intents.attribute}{filter_intents.filter_op}{filter_intents.value}]) mark: {self._mark}, score: {self.score} >"
        else:
            return f"<Vis  ({str_channels[:-2]}) mark: {self._mark}, score: {self.score} >"
    else:
        # When Vis not compiled (e.g., when self._source not populated), print original intent
        return f"<Vis  ({str(self._intent)}) mark: {self._mark}, score: {self.score} >"

def get_attrs_specs(intent):
    if intent is None:
        return []
    spec_obj = list(filter(lambda x: x.value == "", intent))
    return spec_obj

def get_attr_by_data_model(self, dmodel, exclude_record=False):
    if exclude_record:
        return list(
            filter(
                lambda x: x.data_model == dmodel and x.value == ""
                if x.attribute != "Record" and hasattr(x, "data_model")
                else False,
                self._inferred_intent,
            )
        )
    else:
        return list(
            filter(
                lambda x: x.data_model == dmodel and x.value == ""
                if hasattr(x, "data_model")
                else False,
                self._inferred_intent,
            )
        )

def interestingness(vis: Vis, ldf: LuxDataFrame) -> int:
    """
    Compute the interestingness score of the vis.
    The interestingness metric is dependent on the vis type.

    Parameters
    ----------
    vis : Vis
    ldf : LuxDataFrame

    Returns
    -------
    int
            Interestingness Score
    """
    if vis.data is None or len(vis.data) == 0:
        return -1
        # raise Exception("Vis.data needs to be populated before interestingness can be computed. Run Executor.execute(vis,ldf).")
    try:
        filter_specs = utils.get_filter_specs(vis._inferred_intent)
        vis_attrs_specs = utils.get_attrs_specs(vis._inferred_intent)
        n_dim = vis._ndim
        n_msr = vis._nmsr
        n_filter = len(filter_specs)
        attr_specs = [clause for clause in vis_attrs_specs if clause.attribute != "Record"]
        dimension_lst = vis.get_attr_by_data_model("dimension")
        measure_lst = vis.get_attr_by_data_model("measure")
        v_size = len(vis.data)

        if (
            n_dim == 1
            and (n_msr == 0 or n_msr == 1)
            and ldf.current_vis is not None
            and vis.get_attr_by_channel("y")[0].data_type == "quantitative"
            and len(ldf.current_vis) == 1
            and ldf.current_vis[0].mark == "line"
            and len(get_filter_specs(ldf.intent)) > 0
        ):
            query_vc = VisList(ldf.current_vis, ldf)
            query_vis = query_vc[0]
            preprocess(query_vis)
            preprocess(vis)
            return 1 - euclidean_dist(query_vis, vis)

        # Line/Bar Chart
        if n_dim == 1 and (n_msr == 0 or n_msr == 1):
            if v_size < 2:
                return -1

            if vis.mark == "geographical":
                return n_distinct(vis, dimension_lst, measure_lst)
            if n_filter == 0:
                return unevenness(vis, ldf, measure_lst, dimension_lst)
            elif n_filter == 1:
                return deviation_from_overall(vis, ldf, filter_specs, measure_lst[0].attribute)
        # Histogram
        elif n_dim == 0 and n_msr == 1:
            if v_size < 2:
                return -1
            if n_filter == 0 and "Number of Records" in vis.data:
                if "Number of Records" in vis.data:
                    v = vis.data["Number of Records"]
                    return skewness(v)
            elif n_filter == 1 and "Number of Records" in vis.data:
                return deviation_from_overall(vis, ldf, filter_specs, "Number of Records")
            return -1
        # Scatter Plot
        elif n_dim == 0 and n_msr == 2:
            if v_size < 10:
                return -1
            if vis.mark == "heatmap":
                return weighted_correlation(
                    vis.data["xBinStart"], vis.data["yBinStart"], vis.data["count"]
                )
            if n_filter == 1:
                v_filter_size = get_filtered_size(filter_specs, vis.data)
                sig = v_filter_size / v_size
            else:
                sig = 1
            return sig * monotonicity(vis, attr_specs)
        # Scatterplot colored by Dimension
        elif n_dim == 1 and n_msr == 2:
            if v_size < 10:
                return -1
            color_attr = vis.get_attr_by_channel("color")[0].attribute

            C = ldf.cardinality[color_attr]
            if C < 40:
                return 1 / C
            else:
                return -1
        # Scatterplot colored by dimension
        elif n_dim == 1 and n_msr == 2:
            return 0.2
        # Scatterplot colored by measure
        elif n_msr == 3:
            return 0.1
        # colored line and barchart cases
        elif vis.mark == "line" and n_dim == 2:
            return 0.15
        # for colored bar chart, scoring based on Chi-square test for independence score.
        # gives higher scores to colored bar charts with fewer total categories as these charts are easier to read and thus more useful for users
        elif vis.mark == "bar" and n_dim == 2:
            from scipy.stats import chi2_contingency

            measure_column = vis.get_attr_by_data_model("measure")[0].attribute
            dimension_columns = vis.get_attr_by_data_model("dimension")

            groupby_column = dimension_columns[0].attribute
            color_column = dimension_columns[1].attribute

            contingency_tbl = pd.crosstab(
                vis.data[groupby_column],
                vis.data[color_column],
                values=vis.data[measure_column],
                aggfunc=sum,
            )

            try:
                color_cardinality = ldf.cardinality[color_column]
                groupby_cardinality = ldf.cardinality[groupby_column]
                # scale down score based on number of categories
                score = chi2_contingency(contingency_tbl)[0] * 0.9 ** (
                    color_cardinality + groupby_cardinality
                )
            except (ValueError, KeyError):
                # ValueError results if an entire column of the contingency table is 0, can happen if an applied filter results in a category having no counts
                score = -1
            return score
        # Default
        else:
            return -1
    except:
        if lux.config.interestingness_fallback:
            # Supress interestingness related issues
            warnings.warn(f"An error occurred when computing interestingness for: {vis}")
            return -1
        else:
            raise

def get_filtered_size(filter_specs, ldf):
    filter_intents = filter_specs[0]
    result = PandasExecutor.apply_filter(
        ldf, filter_intents.attribute, filter_intents.filter_op, filter_intents.value
    )
    return len(result)

def __repr__(self):
    if len(self._collection) == 0:
        return str(self._input_lst)
    x_channel = ""
    y_channel = ""
    largest_mark = 0
    largest_filter = 0
    # finds longest x attribute among all visualizations
    for vis in self._collection:
        filter_intents = None
        for clause in vis._inferred_intent:
            attr = str(clause.attribute)
            if clause.value != "":
                filter_intents = clause

            if clause.aggregation != "" and clause.aggregation is not None:
                attribute = clause._aggregation_name.upper() + f"({attr})"
            elif clause.bin_size > 0:
                attribute = f"BIN({attr})"
            else:
                attribute = attr
            attribute = str(attribute)
            if clause.channel == "x" and len(x_channel) < len(attribute):
                x_channel = attribute
            if clause.channel == "y" and len(y_channel) < len(attribute):
                y_channel = attribute
        if len(vis.mark) > largest_mark:
            largest_mark = len(vis.mark)
        if (
            filter_intents
            and len(str(filter_intents.value)) + len(str(filter_intents.attribute)) > largest_filter
        ):
            largest_filter = len(str(filter_intents.value)) + len(str(filter_intents.attribute))
    vis_repr = []
    largest_x_length = len(x_channel)
    largest_y_length = len(y_channel)
    # pads the shorter visualizations with spaces before the y attribute
    for vis in self._collection:
        filter_intents = None
        x_channel = ""
        y_channel = ""
        additional_channels = []
        for clause in vis._inferred_intent:
            attr = str(clause.attribute)
            if clause.value != "":
                filter_intents = clause

            if clause.aggregation != "" and clause.aggregation is not None and vis.mark != "scatter":
                attribute = clause._aggregation_name.upper() + f"({attr})"
            elif clause.bin_size > 0:
                attribute = f"BIN({attr})"
            else:
                attribute = attr
            if clause.channel == "x":
                x_channel = attribute.ljust(largest_x_length)
            elif clause.channel == "y":
                y_channel = attribute
            elif clause.channel != "":
                additional_channels.append([clause.channel, attribute])
        if filter_intents:
            y_channel = y_channel.ljust(largest_y_length)
        elif largest_filter != 0:
            y_channel = y_channel.ljust(largest_y_length + largest_filter + 9)
        else:
            y_channel = y_channel.ljust(largest_y_length + largest_filter)
        if x_channel != "":
            x_channel = "x: " + x_channel + ", "
        if y_channel != "":
            y_channel = "y: " + y_channel
        aligned_mark = vis.mark.ljust(largest_mark)
        str_additional_channels = ""
        for channel in additional_channels:
            str_additional_channels += ", " + channel[0] + ": " + channel[1]
        if filter_intents:
            aligned_filter = (
                " -- ["
                + str(filter_intents.attribute)
                + filter_intents.filter_op
                + str(filter_intents.value)
                + "]"
            )
            aligned_filter = aligned_filter.ljust(largest_filter + 8)
            vis_repr.append(
                f" <Vis  ({x_channel}{y_channel}{str_additional_channels} {aligned_filter}) mark: {aligned_mark}, score: {vis.score:.2f} >"
            )
        else:
            vis_repr.append(
                f" <Vis  ({x_channel}{y_channel}{str_additional_channels}) mark: {aligned_mark}, score: {vis.score:.2f} >"
            )
    return "[" + ",\n".join(vis_repr)[1:] + "]"

def get_attr_by_channel(self, channel):
    spec_obj = list(
        filter(
            lambda x: x.channel == channel and x.value == "" if hasattr(x, "channel") else False,
            self._inferred_intent,
        )
    )
    return spec_obj

def data_type(self):
    if not self._data_type:
        self.maintain_metadata()
    return self._data_type

def get_agg_title(clause):
    attr = str(clause.attribute)
    if clause.aggregation is None:
        if len(attr) > 25:
            return attr[:15] + "..." + attr[-10:]
        return f"{attr}"
    elif attr == "Record":
        return f"Number of Records"
    else:
        if len(attr) > 15:
            return f"{clause._aggregation_name.capitalize()} of {attr[:15]}..."
        return f"{clause._aggregation_name.capitalize()} of {attr}"

def sanitize_dataframe(self, df):
    from lux.utils.date_utils import is_timedelta64_series, timedelta64_to_float_seconds

    for attr in df.columns:
        # Check if dtype is unrecognized by Altair (#247)
        if str(df[attr].dtype) == "Float64":
            df[attr] = df[attr].astype(np.float64)

        # Check for timedelta64[...] dtype
        if is_timedelta64_series(df[attr]):
            df[attr] = timedelta64_to_float_seconds(df[attr])

        # Altair can not visualize non-string columns
        # convert all non-string columns in to strings
        df = df.rename(columns={attr: str(attr)})
    return df

def remove_filter_from_spec(self, value):
    new_intent = list(filter(lambda x: x.value != value, self._inferred_intent))
    self.set_intent(new_intent)

def to_JSON(self, rec_infolist, input_current_vis=""):
    widget_spec = {}
    if self.current_vis:
        lux.config.executor.execute(self.current_vis, self)
        widget_spec["current_vis"] = LuxDataFrame.current_vis_to_JSON(
            self.current_vis, input_current_vis
        )
    else:
        widget_spec["current_vis"] = {}
    widget_spec["recommendation"] = []

    # Recommended Collection
    recCollection = LuxDataFrame.rec_to_JSON(rec_infolist)
    widget_spec["recommendation"].extend(recCollection)
    return widget_spec

def current_vis_to_JSON(vlist, input_current_vis=""):
    current_vis_spec = {}
    numVC = len(vlist)  # number of visualizations in the vis list
    if numVC == 1:
        current_vis_spec = vlist[0].to_code(language=lux.config.plotting_backend, prettyOutput=False)
    elif numVC > 1:
        pass
    if vlist[0]._all_column:
        current_vis_spec["allcols"] = True
    else:
        current_vis_spec["allcols"] = False
    return current_vis_spec

