        raise Exception(
            "luxwidget is not installed. Run `pip install luxwidget' to install the Jupyter widget.\nSee more at: https://github.com/lux-org/lux-widget"
        )

def remove_column_from_spec(self, attribute, remove_first: bool = False):
    """
    Removes an attribute from the Vis's clause

    Parameters
    ----------
    attribute : str
            attribute to be removed
    remove_first : bool, optional
            Boolean flag to determine whether to remove all instances of the attribute or only one (first) instance, by default False
    """
    if not remove_first:
        new_inferred = list(filter(lambda x: x.attribute != attribute, self._inferred_intent))
        self._inferred_intent = new_inferred
        self._intent = new_inferred
    elif remove_first:
        new_inferred = []
        skip_check = False
        for i in range(0, len(self._inferred_intent)):
            if self._inferred_intent[i].value == "":  # clause is type attribute
                column_spec = []
                column_names = self._inferred_intent[i].attribute
                # if only one variable in a column, columnName results in a string and not a list so
                # you need to differentiate the cases
                if isinstance(column_names, list):
                    for column in column_names:
                        if (column != attribute) or skip_check:
                            column_spec.append(column)
                        elif remove_first:
                            remove_first = True
                    new_inferred.append(Clause(column_spec))
                else:
                    if column_names != attribute or skip_check:
                        new_inferred.append(Clause(attribute=column_names))
                    elif remove_first:
                        skip_check = True
            else:
                new_inferred.append(self._inferred_intent[i])
        self._intent = new_inferred
        self._inferred_intent = new_inferred

def get_attr_by_data_type(self, dtype):
    return list(
        filter(
            lambda x: x.data_type == dtype and x.value == "" if hasattr(x, "data_type") else False,
            self._inferred_intent,
        )
    )

def to_code(self, language="vegalite", **kwargs):
    """
    Export Vis object to code specification

    Parameters
    ----------
    language : str, optional
        choice of target language to produce the visualization code in, by default "vegalite"

    Returns
    -------
    spec:
        visualization specification corresponding to the Vis object
    """
    if language == "vegalite":
        return self.to_vegalite(**kwargs)
    elif language == "altair":
        return self.to_altair(**kwargs)
    elif language == "matplotlib":
        return self.to_matplotlib()
    elif language == "matplotlib_svg":
        return self._to_matplotlib_svg()
    elif language == "python":
        lux.config.tracer.start_tracing()
        lux.config.executor.execute(lux.vis.VisList.VisList(input_lst=[self]), self._source)
        lux.config.tracer.stop_tracing()
        self._trace_code = lux.config.tracer.process_executor_code(lux.config.tracer_relevant_lines)
        lux.config.tracer_relevant_lines = []
        return self._trace_code
    elif language == "SQL":
        if self._query:
            return self._query
        else:
            warnings.warn(
                "The data for this Vis was not collected via a SQL database. Use the 'python' parameter to view the code used to generate the data.",
                stacklevel=2,
            )
    else:
        warnings.warn(
            "Unsupported plotting backend. Lux currently only support 'altair', 'vegalite', or 'matplotlib'",
            stacklevel=2,
        )

def create_vis(self, vis, standalone=True):
    """
    Input Vis object and return a visualization specification

    Parameters
    ----------
    vis: lux.vis.Vis
            Input Vis (with data)
    standalone: bool
            Flag to determine if outputted code uses user-defined variable names or can be run independently
    Returns
    -------
    chart : altair.Chart
            Output Altair Chart Object
    """
    # Lazy Evaluation for 2D Binning
    if vis.mark == "scatter" and vis._postbin:
        vis._mark = "heatmap"

        PandasExecutor.execute_2D_binning(vis)
    # If a column has a Period dtype, or contains Period objects, convert it back to Datetime
    if vis.data is not None:
        for attr in list(vis.data.columns):
            if pd.api.types.is_period_dtype(vis.data.dtypes[attr]) or isinstance(
                vis.data[attr].iloc[0], pd.Period
            ):
                dateColumn = vis.data[attr]
                vis.data[attr] = pd.PeriodIndex(dateColumn.values).to_timestamp()
            if pd.api.types.is_interval_dtype(vis.data.dtypes[attr]) or isinstance(
                vis.data[attr].iloc[0], pd.Interval
            ):
                vis.data[attr] = vis.data[attr].astype(str)
    fig, ax = matplotlib_setup(4.5, 4)
    if vis.mark == "histogram":
        chart = Histogram(vis, fig, ax)
    elif vis.mark == "bar":
        chart = BarChart(vis, fig, ax)
    elif vis.mark == "scatter":
        chart = ScatterChart(vis, fig, ax)
    elif vis.mark == "line":
        chart = LineChart(vis, fig, ax)
    elif vis.mark == "heatmap":
        chart = Heatmap(vis, fig, ax)
    elif vis.mark == "geographical":
        return AltairRenderer().create_vis(vis, False)
    else:
        chart = None
        return chart
    if chart:
        plt.tight_layout()
        if lux.config.plotting_style and (
            lux.config.plotting_backend == "matplotlib"
            or lux.config.plotting_backend == "matplotlib_svg"
        ):
            chart.ax = lux.config.plotting_style(chart.fig, chart.ax)
        plt.tight_layout()
        tmpfile = BytesIO()
        chart.fig.savefig(tmpfile, format="png")
        chart.chart = base64.b64encode(tmpfile.getvalue()).decode("utf-8")
        plt.clf()
        plt.close("all")
        if self.output_type == "matplotlib_svg":
            return {"config": chart.chart, "vislib": "matplotlib"}
        if self.output_type == "matplotlib":
            if lux.config.plotting_style:
                import inspect

                chart.code += "\n".join(
                    inspect.getsource(lux.config.plotting_style).split("\n    ")[1:-1]
                )
            chart.code += "\nfig"
            chart.code = chart.code.replace("\n\t\t", "\n")
            return chart.code

def create_vis(self, vis, standalone=True):
    """
    Input Vis object and return a visualization specification

    Parameters
    ----------
    vis: lux.vis.Vis
            Input Vis (with data)
    standalone: bool
            Flag to determine if outputted code uses user-defined variable names or can be run independently
    Returns
    -------
    chart : altair.Chart
            Output Altair Chart Object
    """
    # Lazy Evaluation for 2D Binning
    if vis.approx:
        if vis.mark == "scatter" and vis._postbin:
            vis._mark = "heatmap"
            lux.config.executor.execute_2D_binning(vis)
        else:
            # Exactly recompute the selected vis (e.g., top k) to display
            lux.config.executor.execute([vis], vis._original_df, approx=False)
    # If a column has a Period dtype, or contains Period objects, convert it back to Datetime
    if vis.data is not None:
        for attr in list(vis.data.columns):
            if pd.api.types.is_period_dtype(vis.data.dtypes[attr]) or isinstance(
                vis.data[attr].iloc[0], pd.Period
            ):
                dateColumn = vis.data[attr]
                vis.data[attr] = pd.PeriodIndex(dateColumn.values).to_timestamp()
            if pd.api.types.is_interval_dtype(vis.data.dtypes[attr]) or isinstance(
                vis.data[attr].iloc[0], pd.Interval
            ):
                vis.data[attr] = vis.data[attr].astype(str)
            if isinstance(attr, str):
                if "." in attr:
                    attr_clause = vis.get_attr_by_attr_name(attr)[0]
                    # Suppress special character ".", not displayable in Altair
                    # attr_clause.attribute = attr_clause.attribute.replace(".", "")
                    vis._vis_data = vis.data.rename(columns={attr: attr.replace(".", "")})
    if vis.mark == "histogram":
        chart = Histogram(vis)
    elif vis.mark == "bar":
        chart = BarChart(vis)
    elif vis.mark == "scatter":
        chart = ScatterChart(vis)
    elif vis.mark == "line":
        chart = LineChart(vis)
    elif vis.mark == "heatmap":
        chart = Heatmap(vis)
    elif vis.mark == "geographical":
        chart = Choropleth(vis)
    else:
        chart = None

    if chart:
        if lux.config.plotting_style and (
            lux.config.plotting_backend == "vegalite" or lux.config.plotting_backend == "altair"
        ):
            chart.chart = lux.config.plotting_style(chart.chart)
        if self.output_type == "VegaLite":
            chart_dict = chart.chart.to_dict()
            # this is a bit of a work around because altair must take a pandas dataframe and we can only generate a luxDataFrame
            # chart["data"] =  { "values": vis.data.to_dict(orient='records') }
            # chart_dict["width"] = 160
            # chart_dict["height"] = 150
            chart_dict["vislib"] = "vegalite"
            return chart_dict
        elif self.output_type == "Altair":
            import inspect

            if lux.config.plotting_style:
                chart.code += "\n".join(
                    inspect.getsource(lux.config.plotting_style).split("\n    ")[1:-1]
                )
            chart.code += "\nchart"
            chart.code = chart.code.replace("\n\t\t", "\n")

            var = vis._source
            if var is not None:
                all_vars = []
                for f_info in inspect.getouterframes(inspect.currentframe()):
                    local_vars = f_info.frame.f_back
                    if local_vars:
                        callers_local_vars = local_vars.f_locals.items()
                        possible_vars = [
                            var_name for var_name, var_val in callers_local_vars if var_val is var
                        ]
                        all_vars.extend(possible_vars)
                for possible_var in all_vars:
                    if possible_var[0] != "_":
                        print(possible_var)

                found_variable = [
                    possible_var for possible_var in all_vars if possible_var[0] != "_"
                ]
                if len(found_variable) > 0:
                    found_variable = found_variable[0]
                else:
                    found_variable = "df"
            else:  # if vis._source was not set when the Vis was created
                found_variable = "df"
            if standalone:
                chart.code = chart.code.replace(
                    "placeholder_variable",
                    f"pd.DataFrame({str(vis.data.to_dict())})",
                )
            else:
                # TODO: Placeholder (need to read dynamically via locals())
                chart.code = chart.code.replace("placeholder_variable", found_variable)
            return chart.code

def line_or_bar_or_geo(ldf, dimension: Clause, measure: Clause):
    dim_type = dimension.data_type
    # If no aggregation function is specified, then default as average
    if measure.aggregation == "":
        measure.set_aggregation("mean")
    if dim_type == "temporal" or dim_type == "oridinal":
        if isinstance(dimension.attribute, pd.Timestamp):
            # If timestamp, use the _repr_ (e.g., TimeStamp('2020-04-05 00.000')--> '2020-04-05')
            attr = str(dimension.attribute._date_repr)
        else:
            attr = dimension.attribute
        if ldf.cardinality[attr] == 1:
            return "bar", {"x": measure, "y": dimension}
        else:
            return "line", {"x": dimension, "y": measure}
    else:  # unordered categorical
        # if cardinality large than 5 then sort bars
        if ldf.cardinality[dimension.attribute] > 5:
            dimension.sort = "ascending"
        if utils.like_geo(dimension.get_attr()):
            return "geographical", {"x": dimension, "y": measure}
        return "bar", {"x": measure, "y": dimension}

def to_string(self):
    if isinstance(self.attribute, list):
        clauseStr = "|".join(self.attribute)
    elif self.value == "":
        clauseStr = str(self.attribute)
    else:
        clauseStr = f"{self.attribute}{self.filter_op}{self.value}"
    return clauseStr

def intent_to_string(intent):
    if intent:
        return ", ".join([clause.to_string() for clause in intent])
    else:
        return ""

def __repr__(self):
    attributes = []
    if self.description != "":
        attributes.append(f"         description: {self.description}")
    if self.channel != "":
        attributes.append(f"         channel: {self.channel}")
    if self.attribute != "":
        attributes.append(f"         attribute: {str(self.attribute)}")
    if self.filter_op != "=":
        attributes.append(f"         filter_op: {str(self.filter_op)}")
    if self.aggregation != "" and self.aggregation is not None:
        attributes.append("         aggregation: " + self._aggregation_name)
    if self.value != "" or len(self.value) != 0:
        attributes.append(f"         value: {str(self.value)}")
    if self.data_model != "":
        attributes.append(f"         data_model: {self.data_model}")
    if len(self.data_type) != 0:
        attributes.append(f"         data_type: {str(self.data_type)}")
    if self.bin_size != 0:
        attributes.append(f"         bin_size: {str(self.bin_size)}")
    if len(self.exclude) != 0:
        attributes.append(f"         exclude: {str(self.exclude)}")
    attributes[0] = "<Clause" + attributes[0][7:]
    attributes[len(attributes) - 1] += " >"
    return ",\n".join(attributes)

def __repr__(self):
    if self.args == () and self.kwargs == {}:
        return f"<Event: {self.name}>"
    else:
        return f"<Event: {self.name} -- args={self.args}, kwargs={self.kwargs}>"

def remove_deleted_recs(self, change):
    for action in self._widget.deletedIndices:
        deletedSoFar = 0
        for index in self._widget.deletedIndices[action]:
            self._recommendation[action].remove_index(index - deletedSoFar)
            deletedSoFar += 1

def map(self, function):
    # generalized way of applying a function to each element
    return map(function, self._collection)

def get(self, field_name):
    # Get the value of the field for all objects in the collection
    def get_field(d_obj):
        field_val = getattr(d_obj, field_name)
        # Might want to write catch error if key not in field
        return field_val

    return self.map(get_field)

def normalize_score(self, invert_order=False):
    max_score = max(list(self.get("score")))
    for dobj in self._collection:
        dobj.score = dobj.score / max_score
        if invert_order:
            dobj.score = 1 - dobj.score

def sort(self, remove_invalid=True, descending=True):
    # remove the items that have invalid (-1) score
    if remove_invalid:
        self._collection = list(filter(lambda x: x.score != -1, self._collection))
    if lux.config.sort == "none":
        return
    elif lux.config.sort == "ascending":
        descending = False
    elif lux.config.sort == "descending":
        descending = True
    # sort in-place by “score” by default if available, otherwise user-specified field to sort by
    self._collection.sort(key=lambda x: x.score, reverse=descending)

def showK(self):
    k = lux.config.topk
    if k == False:
        return self
    elif isinstance(k, int):
        k = abs(k)
        return VisList(self._collection[:k])

def check_transpose_not_computed(vlist: VisList, a: str, b: str):
    transpose_exist = list(
        filter(
            lambda x: (x._inferred_intent[0].attribute == b) and (x._inferred_intent[1].attribute == a),
            vlist,
        )
    )
    if len(transpose_exist) > 0:
        return transpose_exist[0].score == -1
    else:
        return False

def column_group(ldf):
    recommendation = {
        "action": "Column Groups",
        "description": "Shows charts of possible visualizations with respect to the column-wise index.",
        "long_description": 'A column index can be thought of as an extra column that indicates the values that the user is interested in. \
            Lux focuses on visualizing named dataframe indices, i.e., indices with a non-null name property, as a proxy of the attribute \
                that the user is interested in or have operated on (e.g., group-by attribute). In particular, dataframes with named indices \
                    are often pre-aggregated, so Lux visualizes exactly the values that the dataframe portrays.  \
                        <a href="https://lux-api.readthedocs.io/en/latest/source/advanced/indexgroup.html" target="_blank">More details</a>',
    }
    collection = []
    ldf_flat = ldf
    if isinstance(ldf.columns, pd.DatetimeIndex):
        ldf_flat.columns = ldf_flat.columns.format()

    # use a single shared ldf_flat so that metadata doesn't need to be computed for every vis
    ldf_flat = ldf_flat.reset_index()
    if ldf.index.nlevels == 1:
        if ldf.index.name:
            index_column_name = ldf.index.name
        else:
            index_column_name = "index"
        if isinstance(ldf.columns, pd.DatetimeIndex):
            ldf.columns = ldf.columns.to_native_types()
        for attribute in ldf.columns:
            if ldf[attribute].dtype != "object" and (attribute != "index"):
                vis = Vis(
                    [
                        lux.Clause(
                            attribute=index_column_name,
                            data_type="nominal",
                            data_model="dimension",
                            aggregation="",
                        ),
                        lux.Clause(
                            attribute=attribute,
                            data_type="quantitative",
                            data_model="measure",
                            aggregation=None,
                        ),
                    ]
                )
                collection.append(vis)
    vlst = VisList(collection, ldf_flat)
    # Note that we are not computing interestingness score here because we want to preserve the arrangement of the aggregated ldf

    recommendation["collection"] = vlst
    return recommendation

def recommendation(self):
    from lux.core.frame import LuxDataFrame

    if self._recommendation is not None and self._recommendation == {}:
        if self.name is None:
            self.name = " "
        ldf = LuxDataFrame(self)

        ldf.maintain_metadata()
        ldf.maintain_recs()
        self._recommendation = ldf._recommendation
    return self._recommendation

def _append_rec(self, rec_infolist, recommendations: Dict):
    if recommendations["collection"] is not None and len(recommendations["collection"]) > 0:
        rec_infolist.append(recommendations)

def maintain_recs(self, is_series="DataFrame"):
    # `rec_df` is the dataframe to generate the recommendations on
    # check to see if globally defined actions have been registered/removed
    if lux.config.update_actions["flag"] == True:
        self._recs_fresh = False
    show_prev = False  # flag indicating whether rec_df is showing previous df or current self

    if self._prev is not None:
        rec_df = self._prev
        rec_df._message = Message()
        rec_df.maintain_metadata()  # the prev dataframe may not have been printed before
        last_event = self.history._events[-1].name
        rec_df._message.add(
            f"Lux is visualizing the previous version of the dataframe before you applied <code>{last_event}</code>."
        )
        show_prev = True
    else:
        rec_df = self
        rec_df._message = Message()
    # Add warning message if there exist ID fields
    if len(rec_df) == 0:
        rec_df._message.add(f"Lux cannot operate on an empty {is_series}.")
    elif len(rec_df) < 5 and not rec_df.pre_aggregated:
        rec_df._message.add(
            f"The {is_series} is too small to visualize. To generate visualizations in Lux, the {is_series} must contain at least 5 rows."
        )
    elif self.index.nlevels >= 2 or self.columns.nlevels >= 2:
        rec_df._message.add(
            f"Lux does not currently support visualizations in a {is_series} "
            f"with hierarchical indexes.\n"
            f"Please convert the {is_series} into a flat "
            f"table via pandas.DataFrame.reset_index."
        )
    else:
        id_fields_str = ""
        inverted_data_type = lux.config.executor.invert_data_type(rec_df.data_type)
        if len(inverted_data_type["id"]) > 0:
            for id_field in inverted_data_type["id"]:
                id_fields_str += f"<code>{id_field}</code>, "
            id_fields_str = id_fields_str[:-2]
            rec_df._message.add(f"{id_fields_str} is not visualized since it resembles an ID field.")

    rec_df._prev = None  # reset _prev

    # If lazy, check that recs has not yet been computed
    lazy_but_not_computed = lux.config.lazy_maintain and (
        not hasattr(rec_df, "_recs_fresh") or not rec_df._recs_fresh
    )
    eager = not lux.config.lazy_maintain

    # Check that recs has not yet been computed
    if lazy_but_not_computed or eager:
        is_sql_tbl = lux.config.executor.name == "SQLExecutor"
        rec_infolist = []
        from lux.action.row_group import row_group
        from lux.action.column_group import column_group

        # TODO: Rewrite these as register action inside default actions
        if rec_df.pre_aggregated:
            if rec_df.columns.name is not None:
                rec_df._append_rec(rec_infolist, row_group(rec_df))
            rec_df._append_rec(rec_infolist, column_group(rec_df))
        elif not (len(rec_df) < 5 and not rec_df.pre_aggregated and not is_sql_tbl) and not (
            self.index.nlevels >= 2 or self.columns.nlevels >= 2
        ):
            from lux.action.custom import custom_actions

            # generate vis from globally registered actions and append to dataframe
            custom_action_collection = custom_actions(rec_df)
            for rec in custom_action_collection:
                rec_df._append_rec(rec_infolist, rec)
            lux.config.update_actions["flag"] = False

        # Store _rec_info into a more user-friendly dictionary form
        rec_df._recommendation = {}
        for rec_info in rec_infolist:
            action_type = rec_info["action"]
            vlist = rec_info["collection"]
            if len(vlist) > 0:
                rec_df._recommendation[action_type] = vlist
        rec_df._rec_info = rec_infolist
        rec_df.show_all_column_vis()
        if lux.config.render_widget:
            self._widget = rec_df.render_widget()
    # re-render widget for the current dataframe if previous rec is not recomputed
    elif show_prev:
        rec_df.show_all_column_vis()
        if lux.config.render_widget:
            self._widget = rec_df.render_widget()
    self._recs_fresh = True

