def mapping(self, rmap):
    group_map = {}
    if rmap == {}:
        return {}
    for val in ["quantitative", "id", "nominal", "temporal", "geographical"]:
        group_map[val] = list(filter(lambda x: rmap[x] == val, rmap))
    return group_map

def compute_data_model(self, data_type):
    data_type_inverted = self.invert_data_type(data_type)
    data_model = {
        "measure": data_type_inverted["quantitative"],
        "dimension": data_type_inverted["nominal"]
        + data_type_inverted["temporal"]
        + data_type_inverted["id"]
        + data_type_inverted["geographical"],
    }
    return data_model

def convert_to_list(x):
    """
    "a" --> ["a"]
    ["a","b"] --> ["a","b"]
    """
    if type(x) != list:
        return [x]
    else:
        return x

def reverseMapping(self, map):
    reverse_map = {}
    for valKey in map:
        for val in map[valKey]:
            reverse_map[val] = valKey
    return reverse_map

def populate_data_type_model(ldf, vlist):
    """
    Given a underspecified Clause, populate the data_type and data_model information accordingly

    Parameters
    ----------
    ldf : lux.core.frame
            LuxDataFrame with underspecified intent

    vis_collection : list[lux.vis.Vis]
            List of lux.Vis objects that will have their underspecified Clause details filled out.
    """
    # TODO: copy might not be neccesary
    from lux.utils.date_utils import is_datetime_string

    data_model_lookup = lux.config.executor.compute_data_model_lookup(ldf.data_type)
    for vis in vlist:
        for clause in vis._inferred_intent:
            if clause.description == "?":
                clause.description = ""
            # TODO: Note that "and not is_datetime_string(clause.attribute))" is a temporary hack and breaks the `test_row_column_group` example
            if clause.attribute != "" and clause.attribute != "Record":
                if clause.data_type == "":
                    clause.data_type = ldf.data_type[clause.attribute]
                if clause.data_type == "id":
                    clause.data_type = "nominal"
                if clause.data_type == "geographical":
                    clause.data_type = "nominal"
                if clause.data_model == "":
                    clause.data_model = data_model_lookup[clause.attribute]
            if clause.value != "":
                # If user provided title for Vis, then don't override.
                if vis.title == "":
                    if isinstance(clause.value, np.datetime64):
                        chart_title = date_utils.date_formatter(clause.value, ldf)
                    else:
                        chart_title = clause.value
                    vis.title = f"{clause.attribute} {clause.filter_op} {chart_title}"
        vis._ndim = 0
        vis._nmsr = 0

        for clause in vis._inferred_intent:
            if clause.value == "":
                if clause.data_model == "dimension":
                    vis._ndim += 1
                elif clause.data_model == "measure" and clause.attribute != "Record":
                    vis._nmsr += 1

def execute(view_collection: VisList, tbl: LuxSQLTable, approx: bool = False):
    """
    Given a VisList, fetch the data required to render the view
    1) Generate Necessary WHERE clauses
    2) Query necessary data, applying appropriate aggregation for the chart type
    3) populates vis' data with a DataFrame with relevant results
    """
    for view in view_collection:
        # choose execution method depending on vis mark type

        # when mark is empty, deal with lazy execution by filling the data with a small sample of the dataframe

        if view.mark == "":
            SQLExecutor.execute_sampling(tbl)
            view._vis_data = tbl._sampled
        if view.mark == "scatter":
            where_clause, filterVars = SQLExecutor.execute_filter(view)
            length_query = pandas.read_sql(lux.config.query_templates['length_query'].format(table_name = tbl.table_name, where_clause = where_clause),lux.config.SQLconnection,)
            view_data_length = list(length_query["length"])[0]
            if view_data_length >= lux.config._heatmap_start:
                # NOTE: might want to have a check somewhere to not use categorical variables with greater than some number of categories as a Color variable----------------
                has_color = True
                SQLExecutor.execute_scatter(view, tbl)
            else:
                view._mark = "heatmap"
                SQLExecutor.execute_2D_binning(view, tbl)
        elif view.mark == "heatmap":
            SQLExecutor.execute_2D_binning(view, tbl)
        elif view.mark == "bar" or view.mark == "line":
            SQLExecutor.execute_aggregate(view, tbl)
        elif view.mark == "histogram":
            SQLExecutor.execute_binning(view, tbl)

def create_where_clause(filter_specs, view=""):
    where_clause = []
    filter_vars = []
    filters = filter_specs
    if filters:
        for f in range(0, len(filters)):
            if f == 0:
                where_clause.append("WHERE")
            else:
                where_clause.append("AND")
            curr_value = str(filters[f].value)
            curr_value = curr_value.replace("'", "''")
            if lux.config.handle_quotes == True:
                where_clause.extend(
                    [
                        '"' + str(filters[f].attribute) + '"',
                        str(filters[f].filter_op),
                        "'" + curr_value + "'",
                    ]
                )
            else:
                where_clause.extend(
                    [
                        str(filters[f].attribute),
                        str(filters[f].filter_op),
                        "'" + curr_value + "'",
                    ]
                )
            if filters[f].attribute not in filter_vars:
                filter_vars.append(filters[f].attribute)
    if view != "":
        attributes = utils.get_attrs_specs(view._inferred_intent)

        # need to ensure that no null values are included in the data
        # null values breaks binning queries
        for a in attributes:
            if a.attribute != "Record":
                if where_clause == []:
                    where_clause.append("WHERE")
                else:
                    where_clause.append("AND")
                if lux.config.handle_quotes == True:
                    where_clause.extend(
                        [
                            '"' + str(a.attribute) + '"',
                            "IS NOT NULL",
                        ]
                    )
                else:
                    where_clause.extend(
                        [
                            str(a.attribute),
                            "IS NOT NULL",
                        ]
                    )

    if where_clause == []:
        return ("", [])
    else:
        where_clause = " ".join(where_clause)
    return (where_clause, filter_vars)

