def compute_data_type(self, ldf: LuxDataFrame):
    from pandas.api.types import is_datetime64_any_dtype as is_datetime

    for attr in list(ldf.columns):
        if attr in ldf._type_override:
            ldf._data_type[attr] = ldf._type_override[attr]
        else:
            temporal_var_list = ["month", "year", "day", "date", "time", "weekday"]

            if is_timedelta64_series(ldf[attr]):
                ldf._data_type[attr] = "quantitative"
                ldf._min_max[attr] = (
                    timedelta64_to_float_seconds(ldf[attr].min()),
                    timedelta64_to_float_seconds(ldf[attr].max()),
                )
            elif is_datetime(ldf[attr]):
                ldf._data_type[attr] = "temporal"
            elif self._is_datetime_string(ldf[attr]):
                ldf._data_type[attr] = "temporal"
            elif isinstance(attr, pd._libs.tslibs.timestamps.Timestamp):
                ldf._data_type[attr] = "temporal"
            elif str(attr).lower() in temporal_var_list:
                ldf._data_type[attr] = "temporal"
            elif self._is_datetime_number(ldf[attr]):
                ldf._data_type[attr] = "temporal"
            elif self._is_geographical_attribute(ldf[attr]):
                ldf._data_type[attr] = "geographical"
            elif pd.api.types.is_float_dtype(ldf.dtypes[attr]):

                if ldf.cardinality[attr] != len(ldf) and (ldf.cardinality[attr] < 20):
                    ldf._data_type[attr] = "nominal"
                else:
                    ldf._data_type[attr] = "quantitative"
            elif pd.api.types.is_integer_dtype(ldf.dtypes[attr]):
                # See if integer value is quantitative or nominal by checking if the ratio of cardinality/data size is less than 0.4 and if there are less than 10 unique values
                if ldf.pre_aggregated:
                    if ldf.cardinality[attr] == len(ldf):
                        ldf._data_type[attr] = "nominal"
                if ldf.cardinality[attr] / len(ldf) < 0.4 and ldf.cardinality[attr] < 20:
                    ldf._data_type[attr] = "nominal"
                else:
                    ldf._data_type[attr] = "quantitative"
                if check_if_id_like(ldf, attr):
                    ldf._data_type[attr] = "id"
            # Eliminate this clause because a single NaN value can cause the dtype to be object
            elif pd.api.types.is_string_dtype(ldf.dtypes[attr]):
                # Check first if it's castable to float after removing NaN
                is_numeric_nan, series = is_numeric_nan_column(ldf[attr])
                if is_numeric_nan:
                    # int columns gets coerced into floats if contain NaN
                    ldf._data_type[attr] = "quantitative"
                    # min max was not computed since object type, so recompute here
                    ldf._min_max[attr] = (
                        series.min(),
                        series.max(),
                    )
                elif check_if_id_like(ldf, attr):
                    ldf._data_type[attr] = "id"
                else:
                    ldf._data_type[attr] = "nominal"
            # check if attribute is any type of datetime dtype
            elif is_datetime_series(ldf.dtypes[attr]):
                ldf._data_type[attr] = "temporal"
            else:
                ldf._data_type[attr] = "nominal"
    if not pd.api.types.is_integer_dtype(ldf.index) and ldf.index.name:
        ldf._data_type[ldf.index.name] = "nominal"

    non_datetime_attrs = []
    for attr in ldf.columns:
        if ldf._data_type[attr] == "temporal" and not is_datetime(ldf[attr]):
            non_datetime_attrs.append(attr)
    warn_msg = ""
    if len(non_datetime_attrs) == 1:
        warn_msg += f"\nLux detects that the attribute '{non_datetime_attrs[0]}' may be temporal.\n"
    elif len(non_datetime_attrs) > 1:
        warn_msg += f"\nLux detects that attributes {non_datetime_attrs} may be temporal.\n"
    if len(non_datetime_attrs) > 0:
        warn_msg += "To display visualizations for these attributes accurately, please convert temporal attributes to Datetime objects.\nFor example, you can convert a Year attribute (e.g., 1998, 1971, 1982) using pd.to_datetime by specifying the `format` as '%Y'.\n\nHere is a starter template that you can use for converting the temporal fields:\n"
        for attr in non_datetime_attrs:
            warn_msg += f"\tdf['{attr}'] = pd.to_datetime(df['{attr}'], format='<replace-with-datetime-format>')\n"
        warn_msg += "\nSee more at: https://pandas.pydata.org/pandas-docs/stable/reference/api/pandas.to_datetime.html"
        warn_msg += f"\nIf {attr} is not a temporal attribute, please use override Lux's automatically detected type:"
        warn_msg += f"\n\tdf.set_data_type({{'{attr}':'quantitative'}})"
        warnings.warn(warn_msg, stacklevel=2)

def _is_datetime_string(series):
    if series.dtype == object:
        not_numeric = False
        try:
            pd.to_numeric(series)
        except Exception as e:
            not_numeric = True

        datetime_col = None
        if not_numeric:
            try:
                datetime_col = pd.to_datetime(series)
            except Exception as e:
                return False
        if datetime_col is not None:
            return True
    return False

def _is_geographical_attribute(series):
    # run detection algorithm
    name = str(series.name).lower()
    return utils.like_geo(name)

def _is_datetime_number(series):
    is_int_dtype = pd.api.types.is_integer_dtype(series.dtype)
    if is_int_dtype:
        try:
            temp = series.astype(str)
            pd.to_datetime(temp)
            return True
        except Exception:
            return False
    return False

def validate_clause(clause):
    warn_msg = ""
    if not (clause.attribute == "?" or clause.value == "?" or clause.attribute == ""):
        if isinstance(clause.attribute, list):
            for attr in clause.attribute:
                if attr not in list(ldf.columns):
                    warn_msg = (
                        f"\n- The input attribute '{attr}' does not exist in the DataFrame."
                    )
        else:
            if clause.attribute != "Record":
                # we don't value check datetime since datetime can take filter values that don't exactly match the exact TimeStamp representation
                if isinstance(clause.attribute, str) and not is_datetime_string(
                    clause.attribute
                ):
                    if not clause.attribute in list(ldf.columns):
                        search_val = clause.attribute
                        match_attr = False
                        for attr, val_list in ldf.unique_values.items():
                            if search_val in val_list:
                                match_attr = attr
                        if match_attr:
                            warn_msg = f"\n- The input '{search_val}' looks like a value that belongs to the '{match_attr}' attribute. \n  Please specify the value fully, as something like {match_attr}={search_val}."
                        else:
                            warn_msg = f"\n- The input attribute '{clause.attribute}' does not exist in the DataFrame. \n  Please check your input intent for typos."
                if clause.value != "" and clause.attribute != "" and clause.filter_op == "=":
                    # Skip check for NaN filter values
                    if not lux.utils.utils.like_nan(clause.value):
                        series = ldf[clause.attribute]
                        if not is_datetime_series(series):
                            if isinstance(clause.value, list):
                                vals = clause.value
                            else:
                                vals = [clause.value]
                            for val in vals:
                                if (
                                    lux.config.executor.name == "PandasExecutor"
                                    and val not in series.values
                                ):
                                    warn_msg = f"\n- The input value '{val}' does not exist for the attribute '{clause.attribute}' for the DataFrame."
    return warn_msg

def is_numeric_nan_column(series):
    if series.dtype == object:
        if series.hasnans:
            series = series.dropna()
        try:
            return True, series.astype("float")
        except Exception as e:
            return False, series
    else:
        return False, series

def notebook_enabled() -> tp.Tuple[bool, str]:
    status, nbextension_list = subprocess.getstatusoutput("jupyter nbextension list")

    if status != 0:
        return False, "❌ Failed to run 'jupyter nbextension list'\n"

    match = re.findall(r"config dir:(.*)\n", nbextension_list)

    if match:
        config_dir = match[0].strip()
    else:
        return False, "❌ No 'config dir' found in 'jupyter nbextension list'\n"

    notebook_json = Path(config_dir) / "notebook.json"

    if not notebook_json.exists():
        return False, f"'{notebook_json}' does not exist\n"

    extensions = json.loads(notebook_json.read_text())

    if "load_extensions" not in extensions:
        return False, "❌ 'load_extensions' not in 'notebook.json'\n"
    elif "luxwidget/extension" not in extensions["load_extensions"]:
        return False, "❌ 'luxwidget/extension' not in 'load_extensions'\n"

    extension_enabled = extensions["load_extensions"]["luxwidget/extension"]

    if not extension_enabled:
        return False, "❌ luxwidget is installed but not enabled\n"

    return True, ""

def lab_enabled() -> tp.Tuple[bool, str]:
    status_str, lab_list = subprocess.getstatusoutput("jupyter labextension list")

    if status_str != 0:
        return (
            False,
            "❌ Failed to run 'jupyter labextension list'. Do you have Jupyter Lab installed in this environment?",
        )

    match = re.findall(r"luxwidget (\S+) (\S+) (\S+)", lab_list)

    if match:
        version_str, enabled_str, status_str = (_strip_ansi(s) for s in match[0])
    else:
        return False, "❌ 'luxwidget' not found in 'jupyter labextension list'\n"

    if enabled_str != "enabled":
        enabled_str = re.sub(r"\033\[(\d|;)+?m", "", enabled_str)
        return False, f"❌ luxwidget is installed but currently '{enabled_str}'\n"

    if status_str != "OK":
        return False, f"❌ luxwidget is installed but currently '{status_str}'\n"

    return True, ""

def is_lab_notebook():
    import re
    import psutil

    cmd = psutil.Process().parent().cmdline()

    return any(re.search("jupyter-lab", x) for x in cmd)

def like_nan(val):
    if isinstance(val, str):
        return val.lower() == "nan"
    elif isinstance(val, float) or isinstance(val, int):
        import math

        return math.isnan(val)

def skewness(v):
    from scipy.stats import skew

    return skew(v)

def add_title(self):
    chart_title = self.vis.title
    if chart_title:
        self.ax.set_title(chart_title)
        self.code += f"ax.set_title('{chart_title}')\n"

def weighted_correlation(x, y, w):
    # Based on https://en.wikipedia.org/wiki/Pearson_correlation_coefficient#Weighted_correlation_coefficient
    return weighted_cov(x, y, w) / np.sqrt(weighted_cov(x, x, w) * weighted_cov(y, y, w))

def mutual_information(v_x: list, v_y: list) -> int:
    # Interestingness metric for two measure attributes
    # Calculate maximal information coefficient (see Murphy pg 61) or Pearson's correlation
    from sklearn.metrics import mutual_info_score

    return mutual_info_score(v_x, v_y)

def encode_color(self):
    color_attr = self.vis.get_attr_by_channel("color")
    if len(color_attr) == 1:
        color_attr_name = color_attr[0].attribute
        color_attr_type = color_attr[0].data_type
        if color_attr_type == "temporal":
            timeUnit = compute_date_granularity(self.vis.data[color_attr_name])
            self.chart = self.chart.encode(
                color=alt.Color(
                    str(color_attr_name),
                    type=color_attr_type,
                    timeUnit=timeUnit,
                    title=color_attr_name,
                )
            )
            self.code += f"chart = chart.encode(color=alt.Color('{color_attr_name}',type='{color_attr_type}',timeUnit='{timeUnit}',title='{color_attr_name}'))"
        else:
            self.chart = self.chart.encode(
                color=alt.Color(str(color_attr_name), type=color_attr_type)
            )
            self.code += f"chart = chart.encode(color=alt.Color('{color_attr_name}',type='{color_attr_type}'))\n"
    elif len(color_attr) > 1:
        raise ValueError(
            "There should not be more than one attribute specified in the same channel."
        )

